using MediatR; using TopLab.Application.Common.Interfaces; using TopLab.Application.Common.Results; using TopLab.Domain.Results;
namespace TopLab.Application.Features.CultureResults.Commands.VerifyCultureResult;
public sealed class VerifyCultureResultCommandHandler:IRequestHandler<VerifyCultureResultCommand,Result>{private readonly IApplicationDbContext _db;private readonly ICurrentUserService _user;private readonly IDateTimeProvider _clock;public VerifyCultureResultCommandHandler(IApplicationDbContext db,ICurrentUserService user,IDateTimeProvider clock){_db=db;_user=user;_clock=clock;}public async Task<Result> Handle(VerifyCultureResultCommand r,CancellationToken ct){var pt=_db.Set<PatientTest>().FirstOrDefault(x=>x.Id.Value==r.PatientTestId);if(pt is null)return Result.Failure(Error.NotFound("التحليل غير موجود"));if(_db.Set<CultureResult>().All(x=>x.PatientTestId.Value!=pt.Id.Value))return Result.Failure(Error.Conflict("لا توجد نتيجة مزرعة للاعتماد."));if(!pt.IsReviewed){try{pt.MarkEntered(_user.UserId,_clock.UtcNow);pt.MarkReviewed(_user.UserId,_clock.UtcNow);}catch(InvalidOperationException e){return Result.Failure(Error.Conflict(e.Message));}}await _db.SaveChangesAsync(ct);return Result.Success();}}
